import{_ as a,y as i,a as l,o as d,a2 as s,D as r,g as o,I as e}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Booking Product","description":"","frontmatter":{},"headers":[],"relativePath":"product-types/booking-product.md","filePath":"product-types/booking-product.md","lastUpdated":1789441803000}'),g={name:"product-types/booking-product.md"};function h(p,t,c,u,b,k){const n=i("ImagePopup");return d(),l("div",null,[t[0]||(t[0]=s('<h1 id="booking-product" tabindex="-1">Booking Product <a class="header-anchor" href="#booking-product" aria-label="Permalink to &quot;Booking Product&quot;">​</a></h1><p>A booking product sells time or a place instead of an item: an appointment, a ticket to an event, a rental or a restaurant table. Shoppers pick a date and a slot, or tickets, on the product page, and the booking is placed with their order.</p><p>This page covers what&#39;s specific to booking products. For the sections every product shares, see <a href="./products.html">Products</a>.</p><h2 id="create-a-booking-product" tabindex="-1">Create a booking product <a class="header-anchor" href="#create-a-booking-product" aria-label="Permalink to &quot;Create a booking product&quot;">​</a></h2><p>Create the product as described in <a href="./products.html#create-a-product">Create a product</a>, choosing <strong>Booking</strong> as the <strong>Type</strong>.</p><p>On the edit screen, the booking section comes after <strong>Videos</strong> and starts with <strong>Booking Type</strong>. The settings below it depend on the type you choose.</p><h3 id="how-it-differs-from-other-products" tabindex="-1">How it differs from other products <a class="header-anchor" href="#how-it-differs-from-other-products" aria-label="Permalink to &quot;How it differs from other products&quot;">​</a></h3><ul><li><strong>No Shipping or Inventories section.</strong> Each booking type sets its own capacity instead, such as a quantity per slot or per ticket.</li><li><strong>No Guest Checkout or RMA settings.</strong> Shoppers sign in to book.</li><li><strong>The Price section stays.</strong> How the price is used depends on the type; see <a href="#what-shoppers-pay">What shoppers pay</a>.</li></ul><h2 id="settings-every-booking-has" tabindex="-1">Settings every booking has <a class="header-anchor" href="#settings-every-booking-has" aria-label="Permalink to &quot;Settings every booking has&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Booking Type</strong></td><td><strong>Default Booking</strong>, <strong>Appointment Booking</strong>, <strong>Event Booking</strong>, <strong>Rental Booking</strong> or <strong>Table Booking</strong>.</td></tr><tr><td><strong>Location</strong></td><td>The address shoppers see, with a <strong>View on Map</strong> link. It&#39;s required.</td></tr><tr><td><strong>Qty</strong></td><td>For default, appointment and rental bookings: how many bookings each slot can take. For a rental, that&#39;s how many units can be rented at the same time.</td></tr><tr><td><strong>Available Every Week</strong></td><td>For appointment, rental and table bookings. <strong>Yes</strong> takes bookings every week with no end date. <strong>No</strong> shows <strong>Available From</strong> and <strong>Available To</strong>.</td></tr><tr><td><strong>Available From</strong> and <strong>Available To</strong></td><td>The first and last day bookings can be made for. For an event, the date and time it starts and ends. Once <strong>Available To</strong> has passed, the product can&#39;t be booked.</td></tr><tr><td><strong>Allow Booking Cancellation</strong></td><td><strong>Yes</strong> lets shoppers cancel it by cancelling the order from their account, while the order can still be cancelled. <strong>No</strong> shows a <strong>Cancellation Not Allowed</strong> notice on the product page. The choice is kept with each order, so changing it later doesn&#39;t affect bookings already placed.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Choose the type before you first save</p><p>Once the product is saved with a booking type, <strong>Booking Type</strong> is locked and can&#39;t be changed.</p></div><p>Table bookings use <strong>Guest Capacity</strong> instead of <strong>Qty</strong>, and event bookings set a <strong>Quantity</strong> on each ticket.</p><h2 id="default-booking" tabindex="-1">Default booking <a class="header-anchor" href="#default-booking" aria-label="Permalink to &quot;Default booking&quot;">​</a></h2><p>Use a default booking for something booked in slots you define, such as a banquet hall. <strong>Booking Information</strong> decides how the slots work:</p><ul><li><strong>One Booking For Many Days</strong>: each slot runs from a start day and time to an end day and time, such as Friday 18:00 to Sunday 11:00, and is booked as a whole. <strong>Allow Overlapping Time Slots</strong> decides whether these slots may overlap.</li><li><strong>Many Bookings For One Days</strong>: each day has one opening window, split into slots of <strong>Slot Duration (Mins)</strong> with <strong>Break Time b/w Slots (Mins)</strong> between them.</li></ul>',15)),r(n,{src:"/images/booking-product/booking-default.png",alt:"Default Booking settings with One Booking For Many Days and three slots"}),t[1]||(t[1]=s('<h3 id="add-slots-that-span-days" tabindex="-1">Add slots that span days <a class="header-anchor" href="#add-slots-that-span-days" aria-label="Permalink to &quot;Add slots that span days&quot;">​</a></h3><p>For <strong>One Booking For Many Days</strong>:</p><ol><li>In <strong>Slots Time Duration</strong>, click <strong>Add Slots</strong>. The <strong>Add Slots</strong> panel opens.</li><li>Choose the <strong>From Day</strong> and enter the <strong>From Time</strong>.</li><li>Choose the <strong>To Day</strong> and enter the <strong>To Time</strong>.</li><li>Click <strong>Save</strong>. The slot appears as a label, such as <strong>Fri 18:00 - Sun 11:00</strong>.</li><li>Click <strong>Save Product</strong>.</li></ol>',3)),r(n,{src:"/images/booking-product/booking-default-add-slots.png",alt:"Add Slots panel with From Day, From Time, To Day and To Time"}),t[2]||(t[2]=o("p",null,[e("To remove a slot, click the "),o("strong",null,"×"),e(" on its label. On the storefront, shoppers choose a date that falls on a slot's start day, then the slot.")],-1)),r(n,{src:"/images/booking-product/storefront-default.png",alt:"Storefront booking form for a One Booking For Many Days product"}),t[3]||(t[3]=s('<h3 id="set-daily-opening-hours" tabindex="-1">Set daily opening hours <a class="header-anchor" href="#set-daily-opening-hours" aria-label="Permalink to &quot;Set daily opening hours&quot;">​</a></h3><p>For <strong>Many Bookings For One Days</strong>, <strong>Slots Time Duration</strong> lists the days of the week, each with its window or <strong>Unavailable</strong>.</p><ol><li>Click <strong>Add</strong> next to a day. Once the day has a window, the link reads <strong>Edit</strong>.</li><li>Enter the <strong>From</strong> and <strong>To</strong> time.</li><li>Set the <strong>Status</strong> to <strong>Open</strong>.</li><li>Click <strong>Save</strong>.</li><li>Repeat for each day you&#39;re open.</li><li>Click <strong>Save Product</strong>.</li></ol><p>Each day holds one window; saving the day again replaces it. Save only windows with <strong>Status</strong> set to <strong>Open</strong>, and leave the days you&#39;re closed without a window. On the storefront, shoppers see the <strong>Slot Duration</strong> and choose a date and a slot.</p><h2 id="appointment-booking" tabindex="-1">Appointment booking <a class="header-anchor" href="#appointment-booking" aria-label="Permalink to &quot;Appointment booking&quot;">​</a></h2><p>Use an appointment booking for services booked in time slots, such as consultations.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Slot Duration (Mins)</strong></td><td>The length of each appointment.</td></tr><tr><td><strong>Break Time b/w Slots (Mins)</strong></td><td>The gap between appointments.</td></tr><tr><td><strong>Same Slot For All days</strong></td><td><strong>Yes</strong> uses the same opening hours every day. <strong>No</strong> lets you set hours for each day.</td></tr><tr><td><strong>Allow Overlapping Time Slots</strong></td><td>Whether your opening-hour windows may overlap.</td></tr></tbody></table>',7)),r(n,{src:"/images/booking-product/booking-appointment.png",alt:"Appointment Booking settings with one opening-hours window"}),t[4]||(t[4]=s('<h3 id="set-the-opening-hours" tabindex="-1">Set the opening hours <a class="header-anchor" href="#set-the-opening-hours" aria-label="Permalink to &quot;Set the opening hours&quot;">​</a></h3><p>Appointment, rental and table bookings share the same hours editor.</p><ol><li>In <strong>Slots Time Duration</strong>, click <strong>Add Slots</strong>. When <strong>Same Slot For All days</strong> is <strong>No</strong>, click <strong>Add</strong> next to the day instead.</li><li>Enter the <strong>From</strong> and <strong>To</strong> time of a window.</li><li>To add another window, click <strong>Add Slots</strong> in the panel.</li><li>Click <strong>Save</strong>.</li><li>Click <strong>Save Product</strong>.</li></ol>',3)),r(n,{src:"/images/booking-product/booking-slots-drawer.png",alt:"Slots Time Duration panel with From and To times"}),t[5]||(t[5]=s("<p>Each window must be at least as long as one slot. Bagisto splits every window into bookable slots of <strong>Slot Duration (Mins)</strong>, with the break time between them. For example, a window from 10:00 to 20:00 with 60-minute slots and a 15-minute break gives slots starting at 10:00, 11:15, 12:30 and so on.</p><p>On the storefront, shoppers see the <strong>Slot Duration</strong>. When <strong>Available Every Week</strong> is <strong>Yes</strong>, they also see <strong>Today Availability</strong> and <strong>See Details</strong> for the rest of the week. They then choose a date and a slot under <strong>Book an Appointment</strong>.</p>",2)),r(n,{src:"/images/booking-product/storefront-appointment.png",alt:"Storefront booking form for an appointment"}),t[6]||(t[6]=o("h2",{id:"event-booking",tabindex:"-1"},[e("Event booking "),o("a",{class:"header-anchor",href:"#event-booking","aria-label":'Permalink to "Event booking"'},"​")],-1)),t[7]||(t[7]=o("p",null,[e("Use an event booking to sell tickets for an event, such as a concert. "),o("strong",null,"Available From"),e(" and "),o("strong",null,"Available To"),e(" are the date and time the event starts and ends, and each ticket has its own quantity.")],-1)),r(n,{src:"/images/booking-product/booking-event.png",alt:"Event Booking settings with three tickets"}),t[8]||(t[8]=s('<h3 id="add-tickets" tabindex="-1">Add tickets <a class="header-anchor" href="#add-tickets" aria-label="Permalink to &quot;Add tickets&quot;">​</a></h3><ol><li>In <strong>Tickets</strong>, click <strong>Add Tickets</strong>. The <strong>Add Tickets</strong> panel opens.</li><li>Enter the ticket&#39;s <strong>Name</strong>, such as <strong>VIP Pass</strong>.</li><li>Enter the <strong>Quantity</strong> available.</li><li>Enter the <strong>Price</strong>.</li><li>For a sale price, enter the <strong>Special Price</strong>.</li><li>If the sale has dates, enter <strong>Valid From</strong> and <strong>Valid Until</strong>.</li><li>Enter the <strong>Description</strong>.</li><li>Click <strong>Save</strong>.</li><li>Click <strong>Save Product</strong>.</li></ol>',2)),r(n,{src:"/images/booking-product/booking-event-ticket.png",alt:"Edit Tickets panel with Name, Quantity, Price, Special Price, dates and Description"}),t[9]||(t[9]=o("p",null,[e("Use "),o("strong",null,"Edit"),e(" and "),o("strong",null,"Delete"),e(" on a ticket to change or remove it. Ticket names and descriptions are saved for the language selected at the top of the edit screen.")],-1)),t[10]||(t[10]=o("p",null,[e("On the storefront, shoppers see the event dates, then choose a quantity for each ticket under "),o("strong",null,"Book Your Ticket"),e(". "),o("strong",null,"Your booking"),e(" lists the tickets and the "),o("strong",null,"Total"),e(".")],-1)),r(n,{src:"/images/booking-product/storefront-event.png",alt:"Storefront ticket selection for an event with the booking summary"}),t[11]||(t[11]=s('<h2 id="rental-booking" tabindex="-1">Rental booking <a class="header-anchor" href="#rental-booking" aria-label="Permalink to &quot;Rental booking&quot;">​</a></h2><p>Use a rental booking for things rented by the day or by the hour, such as cars or equipment.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Renting Type</strong></td><td><strong>Daily Basis</strong>, <strong>Hourly Basis</strong> or <strong>Both (Daily and Hourly Basis)</strong>.</td></tr><tr><td><strong>Daily Price</strong></td><td>The rate per day. It appears for <strong>Daily Basis</strong> and <strong>Both</strong>.</td></tr><tr><td><strong>Hourly Price</strong></td><td>The rate per hour. It appears for <strong>Hourly Basis</strong> and <strong>Both</strong>.</td></tr><tr><td><strong>Same Slot For All days</strong></td><td>For hourly rentals: the same rental hours every day, or hours for each day. The hours editor follows, and each window must be at least one hour.</td></tr></tbody></table>',3)),r(n,{src:"/images/booking-product/booking-rental.png",alt:"Rental Booking settings with daily and hourly prices"}),t[12]||(t[12]=o("p",null,[e("On the storefront, shoppers offered both options choose "),o("strong",null,"Daily Basis"),e(" or "),o("strong",null,"Hourly Basis"),e(" under "),o("strong",null,"Choose Rent Option"),e(". For an hourly rental they choose a date, a slot and the hours, at least one hour in total; for a daily rental, the start and end dates. "),o("strong",null,"Your rental"),e(" shows the total.")],-1)),r(n,{src:"/images/booking-product/storefront-rental.png",alt:"Storefront rental form with the Choose Rent Option choice"}),t[13]||(t[13]=s('<h2 id="table-booking" tabindex="-1">Table booking <a class="header-anchor" href="#table-booking" aria-label="Permalink to &quot;Table booking&quot;">​</a></h2><p>Use a table booking for restaurant reservations.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Charged Per</strong></td><td><strong>Guest</strong> charges the price for each guest. <strong>Table</strong> charges it for each table.</td></tr><tr><td><strong>Guest Limit Per Table</strong></td><td>How many guests one table seats. It appears when <strong>Charged Per</strong> is <strong>Table</strong>.</td></tr><tr><td><strong>Guest Capacity</strong></td><td>How many guests can book each slot.</td></tr><tr><td><strong>Slot Duration (Mins)</strong></td><td>The length of each seating.</td></tr><tr><td><strong>Break Time b/w Slots (Mins)</strong></td><td>The gap between seatings.</td></tr><tr><td><strong>Prevent Scheduling Before</strong></td><td>How many days ahead shoppers must book. With <strong>1</strong>, the earliest date they can choose is tomorrow.</td></tr><tr><td><strong>Same Slot For All days</strong></td><td>The same opening hours every day, or hours for each day.</td></tr><tr><td><strong>Allow Overlapping Time Slots</strong></td><td>Whether your opening-hour windows may overlap.</td></tr></tbody></table>',3)),r(n,{src:"/images/booking-product/booking-table.png",alt:"Table Booking settings charged per table"}),t[14]||(t[14]=s("<p>On the storefront, shoppers see the <strong>Slot Duration</strong> and, when <strong>Available Every Week</strong> is <strong>Yes</strong>, <strong>Today Availability</strong> with <strong>Show for all days</strong>. They choose a date and a slot under <strong>Book a Table</strong>, and can leave a <strong>Special Request/Notes</strong>.</p>",1)),r(n,{src:"/images/booking-product/storefront-table.png",alt:"Storefront table booking form with Special Request/Notes"}),t[15]||(t[15]=s('<h2 id="what-shoppers-pay" tabindex="-1">What shoppers pay <a class="header-anchor" href="#what-shoppers-pay" aria-label="Permalink to &quot;What shoppers pay&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Price</th></tr></thead><tbody><tr><td>Default and appointment</td><td>The product&#39;s price for each booking.</td></tr><tr><td>Event</td><td>Each ticket&#39;s price. When the product has a price, it&#39;s added as a base fee for each ticket.</td></tr><tr><td>Rental</td><td>The product&#39;s price as a base rental fee, plus the daily or hourly rate for the time rented.</td></tr><tr><td>Table</td><td>The product&#39;s price for each guest or each table, depending on <strong>Charged Per</strong>.</td></tr></tbody></table><p>The page of an event or rental product shows a <strong>Starting from</strong> price: the product&#39;s price plus the cheapest ticket or the lowest rental rate.</p><h2 id="manage-bookings" tabindex="-1">Manage bookings <a class="header-anchor" href="#manage-bookings" aria-label="Permalink to &quot;Manage bookings&quot;">​</a></h2><p>Every booking placed with an order is listed under <strong>Sales &gt;&gt; Bookings</strong>, in a week calendar or as a list. How to find a booking and open its order is described in <a href="./../orders/bookings.html">Bookings</a>.</p><h2 id="cancelling-bookings" tabindex="-1">Cancelling bookings <a class="header-anchor" href="#cancelling-bookings" aria-label="Permalink to &quot;Cancelling bookings&quot;">​</a></h2><p>When <strong>Allow Booking Cancellation</strong> is <strong>No</strong>, shoppers can&#39;t cancel the booking from their account; if they cancel an order, its bookings stay in place. You can still cancel the order from the admin panel.</p>',7))])}const T=a(g,[["render",h]]);export{m as __pageData,T as default};
